function Button({children,onClick,variant='primary',className='',type='button',disabled=false}:{children:ReactNode;onClick?:()=>void;variant?:'primary'|'quiet'|'outline'|'danger';className?:string;type?:'button'|'submit';disabled?:boolean}) { return <button type={type} disabled={disabled} onClick={onClick} data-testid={`button-${typeof children==='string'?children.toLowerCase().replaceAll(' ','-'):'action'}`} className={cn("inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold transition-all active:scale-[.98] disabled:cursor-not-allowed disabled:opacity-50",variant==='primary'&&"bg-primary text-primary-foreground hover:brightness-110",variant==='quiet'&&"bg-secondary text-secondary-foreground hover:bg-muted",variant==='outline'&&"border border-border bg-card hover:bg-secondary",variant==='danger'&&"bg-destructive text-destructive-foreground",className)}>{children}</button>; }
