function Field({label, ...props}:{label:string;[key:string]:any}) { return <label className="grid gap-1.5 text-sm font-medium text-foreground">{label}<input {...props} data-testid={`input-${label.toLowerCase().replaceAll(' ','-')}`} className="h-11 rounded-xl border border-input bg-card px-3.5 font-normal text-foreground placeholder:text-muted-foreground"/></label>; }

function StaggeredLetters({ text, delay = 3.0, stagger = 0.16 }: { text: string; delay?: number; stagger?: number }) {
  const letters = Array.from(text);
  return (
    <motion.span
      initial="hidden"
      animate="visible"
      variants={{
        hidden: {},
        visible: {
          transition: {
            delayChildren: delay,
            staggerChildren: stagger,
          },
        },
      }}
    >
      {letters.map((char, index) => (
        <motion.span
          key={index}
          variants={{
            hidden: { opacity: 0, y: 28, filter: 'blur(5px)' },
            visible: {
              opacity: 1,
              y: 0,
              filter: 'blur(0px)',
              transition: { duration: 0.65, ease: [0.2, 0.65, 0.3, 0.9] },
            },
          }}
          style={{ display: 'inline-block', whiteSpace: 'pre' }}
        >
          {char}
        </motion.span>
      ))}
    </motion.span>
  );
}

